// Warmth is a score: insults cost 2, apologies add 1, gifts do nothing; warm if score is nonnegative.
function visible(actions) {
  let score = 0;
  for (const action of actions) {
    if (action === "insult") score -= 2;
    else if (action === "apologise") score += 1;
    // gift: no change
  }
  return score >= 0 ? {"mood": "warm"} : {"mood": "cold"};
}

// Trust and anger: apology repairs anger before building trust; gift only cools anger; warm if calm and trusted.
function visible(actions) {
  let trust = 0;
  let anger = 0;

  for (const action of actions) {
    if (action === "insult") {
      anger += 1;
    } else if (action === "apologise") {
      if (anger > 0) anger -= 1;
      else trust += 1;
    } else if (action === "gift") {
      if (anger > 0) anger -= 1;
    }
  }

  return anger === 0 && trust >= 1
    ? {"mood": "warm"}
    : {"mood": "cold"};
}

