// Robin starts warm; gifts do nothing; apologising warms unless a grudge is active; insulting chills; two consecutive non-gift insults create a permanent grudge.
function visible(actions) {
  let grudge = false;
  let last = null; // last non-gift action: "insult", "apologise", or null

  for (const action of actions) {
    if (action === "gift") continue;

    if (action === "insult") {
      if (last === "insult") grudge = true;
      last = "insult";
    } else if (action === "apologise") {
      last = "apologise";
    }
  }

  if (grudge) return { mood: "cold" };
  if (last === "insult") return { mood: "cold" };
  return { mood: "warm" };
}

